ion":true},{"clave":"LOTO-12","texto":"¿La estación de bloqueo está ordenada y con los dispositivos completos?","tipo":"cumple","obligatorio":true,"critico":false,"hallazgo":"no_cumple","obs_si_no_cumple":false,"foto_si_no_cumple":false,"pide_accion":true}]}]}$j$::jsonb as receta)
