-- Revisión final: las 6 recetas pasan la misma revisión que se exige para publicar.
do $$ declare v record; begin
  for v in select receta from public.plantillas_versiones where empresa_id is null loop
    perform app.validar_receta(v.receta, true);
  end loop;
end $$;
